    // "br" (breton, ISO 639-1) : reconnu "langue de France" (DGLFLF), écoles immersives Diwan,
    // ~200 000 locuteurs — Bretagne. Langue celtique (mutations consonantiques), structurellement
    // bien plus éloignée du français que le catalan/l'occitan/le corse : niveau de confiance un cran
    // en dessous de ces trois-là (comparable au sorabe/frison du Nord), une relecture par un
    // locuteur natif reste plus utile ici que pour les langues romanes de ce même lot.
